from base_sensor import BaseVirtualSensor

class LIS2DW12_Simulator(BaseVirtualSensor):
    def __init__(self):
        super().__init__()
        self.regs = {
            0x0D: 0x00,  # OUT_T_L
            0x0E: 0x00,  # OUT_T_H
            0x0F: 0x44,  # WHO_AM_I
            0x20: 0x00,  # CTRL1
            0x21: 0x04,  # CTRL2
            0x23: 0x00,  # CTRL4_INT1_PAD_CTRL
            0x24: 0x00,  # CTRL5_INT2_PAD_CTRL
            0x26: 0x00,  # OUT_T
            0x27: 0x00,  # STATUS
            0x2E: 0x00,  # FIFO_CTRL
            0x2F: 0x00,  # FIFO_SAMPLES
            0x38: 0x00,  # WAKE_UP_SRC
            0x3C: 0x00,  # X_OFS_USR
            0x3D: 0x00,  # Y_OFS_USR
            0x3E: 0x00,  # Z_OFS_USR
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr in self.regs:
            if nbytes == 2:
                return self.regs[addr]
            elif nbytes == 1:
                return (self.regs[addr] >> 8) & 0xFF
        return 0

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr in self.regs:
            if nbytes == 2:
                self.regs[addr] = data
            elif nbytes == 1:
                self.regs[addr] &= 0x00FF
                self.regs[addr] |= (data << 8)

        if addr == 0x21 and (data & (1 << 6)):
            # Soft reset logic
            self.regs[0x21] &= ~(1 << 6)
            self.regs[0x21] |= 0x04  # Reset to default value

        if addr == 0x38:
            # Clear interrupt flags on read
            self.regs[0x38] &= 0xC0  # Keep bits 7:6, clear others
